def quotas(weights, seats):
    """Compute base allocation and integer remainders for Hamilton method.

    Parameters
    ----------
    weights : dict[str, int]
        Mapping of names to non‑negative integer weights.
    seats : int
        Total number of seats to allocate.

    Returns
    -------
    tuple[dict[str, int], dict[str, int]]
        ``base`` – floor allocation for each name.
        ``remainders`` – integer remainder for each name.

    Raises
    ------
    ValueError
        If inputs are invalid according to the specification.
    """
    if type(seats) is not int or seats < 0:
        raise ValueError("invalid allocation")
    if not isinstance(weights, dict):
        raise ValueError("invalid allocation")
    for k, v in weights.items():
        if type(v) is not int or v < 0:
            raise ValueError("invalid allocation")
    total = sum(weights.values())
    if total == 0:
        if seats:
            raise ValueError("zero total")
        return {k: 0 for k in weights}, {k: 0 for k in weights}
    base = {k: seats * v // total for k, v in weights.items()}
    remainders = {k: seats * v % total for k, v in weights.items()}
    return base, remainders

